INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261116-celtics-mavericks', 'celtics-131-mavericks-94-tatum-32-sixth-straight-win', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Celtics 131, Mavericks 94: Jayson Tatum scores 32 as Boston wins a sixth straight game', 'Boston scored 42 points in the first quarter at TD Garden on Sunday, Nov. 15, and led 50-15 midway through the second quarter.', 'The Boston Celtics routed the Dallas Mavericks 131-94 at TD Garden on Sunday, Nov. 15, putting the game away in the first quarter. Boston scored 42 points in the opening period and held Dallas to nine, and the Celtics led 50-15 with 8:59 left in the second quarter, according to ESPN''s game page.

## The Celtics

Jayson Tatum led everyone with 32 points on 11-of-18 shooting, including 5 of 8 from 3-point range, along with six rebounds and six assists in a game in which he was plus-31, according to the NBA.com box score. Derrick White added 16 points, Jordan Walsh scored 11 and Payton Pritchard 10. Paul George had seven points, seven rebounds and six assists and finished plus-33. Baylor Scheierman scored 12, Sports Illustrated''s scoreboard showed.

## The Mavericks

Zaccharie Risacher scored 18 points on 8-of-9 shooting for Dallas. Rookie Cooper Flagg had 17 points but made only 5 of 15 shots. Walter Clayton Jr. and Naji Marshall scored 13 each. The Mavericks shot 39.8 percent from the field, made 14 of 41 3-point attempts and committed 17 turnovers.

## The standings

The Celtics came in at 10-2, 5-0 at home and on a five-game winning streak, ESPN listed before tip-off, so the win made them 11-2 with six straight victories. Dallas had arrived at 7-6.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:57200:57232/full/pct:25/0/default.jpg', 'Aerial view of Boston and the Charles River (file). Photo: Carol M. Highsmith / Library of Congress (highsm.57232), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-16.sql', 8, 0, 'newsroom-assistant', '2026-11-16T10:50:00.000Z', '2026-11-16T10:50:00.000Z');
