INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261116-niners-cowboys', '49ers-46-cowboys-40-purdy-career-best-389-yards-mccaffrey', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, '49ers 46, Cowboys 40: Brock Purdy throws for a career-best 389 yards as San Francisco holds off Dallas', 'Christian McCaffrey piled up 223 yards from scrimmage and scored three times at AT&T Stadium on Sunday night, Nov. 15. Dak Prescott threw five touchdown passes in the loss.', 'The San Francisco 49ers beat the Dallas Cowboys 46-40 in a Sunday night shootout at AT&T Stadium in Arlington, Texas, on Nov. 15, CBS Texas reported.

## San Francisco''s big plays

Brock Purdy completed 22 of 28 passes for a career-best 389 yards. Two of his touchdown passes went to Christian McCaffrey, covering 74 and 66 yards. McCaffrey finished with 223 yards from scrimmage, 161 receiving and 62 rushing, and also ran for a 16-yard touchdown. Deebo Samuel scored on a 70-yard reverse, and Kaelon Black opened the second half with a 25-yard touchdown run.

## Dallas comes back, then runs out of time

Dak Prescott completed 30 of 51 passes for 343 yards and five touchdowns, tying his career high. George Pickens caught three of the touchdown passes and finished with 145 receiving yards; Ryan Flournoy and CeeDee Lamb caught the others. Dallas cut a 19-point deficit to six before McCaffrey''s 66-yard catch-and-run in the final four minutes put the game away, according to CBS Texas.

## The records

San Francisco improved to 8-1. Dallas fell to 4-6.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:30500:30586/full/pct:25/0/default.jpg', 'The video board inside AT&T Stadium, home of the Dallas Cowboys, in Arlington, Texas (file). Photo: Carol M. Highsmith / Library of Congress (highsm.30586), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-16.sql', 7, 0, 'newsroom-assistant', '2026-11-16T10:50:00.000Z', '2026-11-16T10:50:00.000Z');
