INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261116-bills-jets', 'bills-31-jets-12-josh-allen-three-touchdowns-buffalo-8-1', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Bills 31, Jets 12: Josh Allen accounts for three touchdowns as Buffalo moves to 8-1', 'James Cook ran for 157 yards, including a 74-yard score, at MetLife Stadium on Sunday, Nov. 15. Buffalo now leads a division in which the Patriots sit at 5-5.', 'The Buffalo Bills beat the New York Jets 31-12 at MetLife Stadium on Sunday, Nov. 15, for their fifth straight win and their first AFC East victory of the season, according to the team''s game recap.

## Allen''s day

Josh Allen completed 11 of 21 passes for 196 yards, with a 45-yard touchdown to DJ Moore and one interception. He also scored twice on 1-yard quarterback sneaks. The second was the 90th rushing touchdown of his career, and his 323rd total touchdown moved him past Peyton Manning for the most total touchdowns by a player through his first 10 seasons, the Bills said.

## Cook breaks one

James Cook ran for 157 yards on 18 carries. His 74-yard touchdown run in the fourth quarter was the longest of his career and the longest rushing touchdown by a Bill since LeSean McCoy went 75 yards in 2016. Moore led Buffalo with four catches for 90 yards, and rookie T.J. Parker had two sacks early in the fourth quarter.

## The Jets

The Jets'' starting quarterback went 13 of 21 for 148 yards before he took a hard hit late in the first half and left with a concussion, according to the Bills'' recap. Fourth-round rookie Cade Klubnik, from Clemson, played the rest of the way in his first NFL action, completing 11 of 20 passes for 137 yards with an interception.

## The standings

Buffalo improved to 8-1. The Jets fell to 2-8. In the AFC East, the Patriots dropped to 5-5 with their loss to Detroit the same day.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:52600:52612/full/pct:25/0/default.jpg', 'Aerial view of Buffalo, New York (file). Photo: Carol M. Highsmith / Library of Congress (highsm.52612), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-16.sql', 6, 0, 'newsroom-assistant', '2026-11-16T10:50:00.000Z', '2026-11-16T10:50:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261116-bills-jets-src1', 'bd-20261116-bills-jets', 'Bills 31, Jets 12 | Final score, recap, highlights', 'https://www.buffalobills.com/news/bills-31-jets-12-final-score-recap-highlights', 'Buffalo Bills', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-16T10:50:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-16. Editor to confirm.', 'newsroom-assistant', '2026-11-16T10:50:00.000Z');
