INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261116-red-sox-bauers', 'red-sox-jake-bauers-four-year-58-million-deal-nlcs-mvp', 'newsroom', 'news_story', 'mlb', 'EDITORIAL_REVIEW', 0, 'Red Sox agree to a four-year, $58 million deal with NLCS MVP Jake Bauers, MLB.com source says', 'The left-handed hitter helped Milwaukee win the World Series. The deal, reported on Friday, Nov. 13, is pending a physical and has not been announced by the club.', 'The Boston Red Sox have agreed to a four-year, $58 million contract with first baseman Jake Bauers, a source told MLB.com''s Mark Feinsand. ESPN''s Jeff Passan was first to report the deal on Friday, Nov. 13. It is pending a physical and the Red Sox have not announced it, MLB.com reported. MLB.com called it the biggest signing of the offseason so far.

## Why Boston wanted him

Bauers had a career year for the Milwaukee Brewers in 2026, batting .266 with a .389 on-base percentage, 26 home runs and 86 RBIs in 578 plate appearances. He was named MVP of the National League Championship Series after the Brewers swept the Los Angeles Dodgers, a series that included a go-ahead home run off Blake Snell in Game 3. He struggled in the World Series, which Milwaukee won in five games over the Tampa Bay Rays.

The Red Sox finished 26th in the majors in home runs and 20th in slugging percentage in 2026, and the signing is aimed at that gap, according to MLB.com.

## Where he fits

Bauers, a left-handed hitter, played mostly first base for Milwaukee and also saw time in left and right field. MLB.com reported that Willson Contreras is expected to take most of Boston''s first-base at-bats, so Bauers could see time at designated hitter. That raises questions about Masataka Yoshida, the primary DH option, who is entering the last year of his contract, and about an outfield projected to include Roman Anthony, Ceddanne Rafaela, Wilyer Abreu and Jarren Duran.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:ggbain:10800:10855/full/pct:50/0/default.jpg', 'Fenway Park, Boston, seen from the right-field corner in September 1914 (archival). Photo: Bain News Service / Library of Congress (ggbain.10855), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-16.sql', 6, 0, 'newsroom-assistant', '2026-11-16T10:50:00.000Z', '2026-11-16T10:50:00.000Z');
