INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261116-trump-asia-trip', 'trump-asia-trip-manila-shenzhen-apec-xi-putin-trilateral', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'Trump heads to Asia with a stop in Manila before APEC talks with Xi and Putin in Shenzhen', 'The trip comes after Republican losses in the midterms and as the Nvidia scandal hangs over relations with Beijing. A senior official says the spy allegations are not expected to come up with Xi.', 'President Donald Trump travels to Asia for a trip that begins with meetings with Southeast Asian and other regional leaders in Manila on Tuesday, Nov. 17, Reuters reported in a story published on Monday, Nov. 16. From there he goes to Shenzhen, China, for the Asia-Pacific Economic Cooperation forum, where he is to meet Chinese President Xi Jinping and hold three-way talks with Xi and Russian President Vladimir Putin.

## On the table

Reuters reported that possible topics include nuclear arms control, denuclearization agreements with Beijing and Moscow, and arranging a meeting with North Korean leader Kim Jong Un, for which Trump may seek help from Xi and Putin. A senior U.S. official said Trump is not expected to raise Ukraine with Xi. Chinese analysts told Reuters that a nuclear arms control deal is a non-starter for China, which has far fewer warheads than the United States or Russia.

## The Nvidia shadow

The trip follows the resignation of Nvidia chief executive Jensen Huang amid allegations involving a suspected Chinese spy. Critics say the administration failed to act on intelligence about Huang, and there are claims that restricted chips were diverted to Chinese customers, Reuters reported. A senior administration official said the matter should not affect the trip and that Trump is not expected to raise the spy allegations with Xi. China says the United States invented the spy story to justify blocking its access to technology.

## Trade and Taiwan

The U.S.-China trade truce has been extended to Jan. 10, and Trump and Xi are due to meet again in December at the G20 summit in Miami. Reuters reported that Beijing''s top priority is keeping Trump from approving a $14 billion arms package for Taiwan, which Trump has described as a negotiating chip.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:04700:04799/full/pct:25/0/default.jpg', 'Aerial view of the Washington Monument and the White House (file). Photo: Carol M. Highsmith / Library of Congress (highsm.04799), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-16.sql', 8, 0, 'newsroom-assistant', '2026-11-16T10:50:00.000Z', '2026-11-16T10:50:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261116-trump-asia-trip-src1', 'bd-20261116-trump-asia-trip', 'Trump''s Asia trip to include summit with Xi, Putin (Reuters)', 'https://www.staradvertiser.com/2026/11/16/breaking-news/trumps-asia-trip-to-include-summit-with-xi-putin/', 'Reuters via Honolulu Star-Advertiser', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-16T10:50:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-16. Editor to confirm.', 'newsroom-assistant', '2026-11-16T10:50:00.000Z');
INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261116-trump-asia-trip-ev1', 'bd-20261116-trump-asia-trip', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'Drafted from attributed reporting and primary sources; awaiting editor approval', '2026-11-16T10:50:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261116-alaska-senate-count', 'peltola-157-votes-short-majority-alaska-senate-ranked-choice-nov-18', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Peltola sits 157 votes short of an outright majority in Alaska''s Senate race as a ranked-choice count looms', 'Democrat Mary Peltola leads Sen. Dan Sullivan by 11,213 first-choice votes in the latest state tally. If she stays under 50 percent, ranked-choice tabulation begins on Wednesday, Nov. 18.', 'Democrat Mary Peltola held 49.94 percent of first-choice votes in Alaska''s U.S. Senate race in an unofficial state summary released on Saturday, Nov. 14, leaving her 157 votes short of an outright majority, Newsweek reported. Republican Sen. Dan Sullivan had 45.96 percent.

## The numbers

According to the Alaska Division of Elections summary cited by Newsweek, Peltola had 140,637 first-choice votes and Sullivan had 129,424, a gap of 11,213. Republican Gerald Heikes had 6,002 votes, Daniel J. Sullivan Jr. had 4,652 and write-ins totaled 872. The Associated Press estimated that 97 percent of the vote had been counted as of Sunday morning, Nov. 15, and had not called the race.

## What happens next

A candidate who wins more than 50 percent of first-choice votes wins outright. If no one does, the Division of Elections will begin ranked-choice tabulation on Wednesday, Nov. 18, eliminating the last-place candidate in each round and moving those ballots to voters'' next choices until someone passes 50 percent. Overseas ballots can still arrive through Nov. 18, and certification is targeted for Wednesday, Nov. 25, Newsweek reported.

Newsweek''s own analysis of scanned ballots showed Peltola winning a two-candidate final round with 51.83 percent. That is not an official result. Sullivan''s campaign has not conceded.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:04400:04433/full/pct:25/0/default.jpg', 'The skyline of Juneau, Alaska (file). Photo: Carol M. Highsmith / Library of Congress (highsm.04433), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-16.sql', 7, 0, 'newsroom-assistant', '2026-11-16T10:50:00.000Z', '2026-11-16T10:50:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261116-alaska-senate-count-src1', 'bd-20261116-alaska-senate-count', 'Mary Peltola Closes in on 50% Threshold in Alaska Senate Race', 'https://www.newsweek.com/mary-peltola-closes-in-on-50-threshold-in-alaska-senate-race-12718013', 'Newsweek', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-16T10:50:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-16. Editor to confirm.', 'newsroom-assistant', '2026-11-16T10:50:00.000Z');
