INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261116-faa-funding-push', 'trump-urges-congress-air-traffic-control-money-routers-arkansas-texas', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'Trump presses Congress for air traffic control money as investigators study routers in Arkansas and Texas', 'Two days after the nationwide ground stop, the president said the upgrade should not come in "drips and drabs." Transportation Secretary Sean Duffy said flights should be at full capacity by Monday, Nov. 16.', 'President Donald Trump broke his silence on the nationwide ground stop on Sunday, Nov. 15, urging Congress in a Truth Social post to approve money to overhaul the air traffic control system, the Associated Press reported. Trump said the upgrade should not be done in "drips and drabs," called the age of much of the system ridiculous, and accused the Biden administration of making it worse.

## The money fight

Transportation Secretary Sean Duffy wants Congress to provide billions of dollars more. He described the $12.5 billion that the Republican-controlled Congress approved for the Federal Aviation Administration last year, as part of a tax cut package, as a down payment, the AP reported. Biden''s infrastructure law set aside $25 billion for the FAA. Duffy said blame lies with both parties after decades of underinvestment, and said carriers such as AT&T, Verizon and Lumen could deploy a new network quickly if it were funded.

## What investigators are looking at

Officials are analyzing two routers installed at FAA facilities in El Dorado, Arkansas, and Amarillo, Texas, according to the AP. The trouble reportedly began when a contractor replaced old copper wire with fiber, overloading the system, and work by federal contractor L3Harris Technologies is under review. Duffy said there were no signs of a cyberattack.

The ground stop was ordered on Friday, Nov. 13. Duffy said air travel should be back at full capacity by Monday, Nov. 16.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:17500:17598/full/pct:25/0/default.jpg', 'A terminal at Ronald Reagan Washington National Airport (file). Photo: Carol M. Highsmith / Library of Congress (highsm.17598), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-16.sql', 7, 0, 'newsroom-assistant', '2026-11-16T10:50:00.000Z', '2026-11-16T10:50:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261116-faa-funding-push-src1', 'bd-20261116-faa-funding-push', 'Trump administration asks for billions to overhaul FAA. Democrats question how money was spent (AP)', 'https://ca.finance.yahoo.com/news/trump-breaks-silence-nationwide-ground-141920287.html', 'Associated Press via Yahoo Finance', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-16T10:50:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-16. Editor to confirm.', 'newsroom-assistant', '2026-11-16T10:50:00.000Z');
