INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261116-scotus-universal-vacatur', 'trump-administration-asks-supreme-court-limit-courts-voiding-rules-nationwide', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Trump administration asks the Supreme Court to stop judges from striking down federal rules nationwide', 'The appeal grows out of a Texas fight over surprise medical billing rules. It would build on the 2025 ruling that curbed universal injunctions.', 'The Justice Department has asked the Supreme Court to bar lower courts from setting aside federal agency regulations for everyone under the Administrative Procedure Act, Reuters reported on Saturday, Nov. 14. Under the administration''s approach, relief would apply only to the plaintiffs who bring a case.

## The case

The appeal comes from a challenge by Texas medical providers, including a doctors'' association and air-ambulance companies, to federal rules that limit surprise bills from out-of-network providers. In August, the 5th U.S. Circuit Court of Appeals in New Orleans voided parts of the rule nationwide. The administration is not contesting that ruling on the merits; it is challenging the courts'' power to wipe the rule out everywhere, Reuters reported.

## Why it matters

The request would extend the limits the justices placed on universal injunctions in June 2025 in the birthright citizenship litigation. University of Virginia law professor Aditya Bamzai told Reuters that a win for the administration could let the government keep enforcing a rule against everyone except the plaintiffs. Washington University law professor Ronald Levin argued that some rules only work if they apply uniformly. Texas, Florida and other mostly Republican-led states had urged the 5th Circuit to preserve the APA''s reach. The Biden administration sought similar limits in 2023, but the justices declined to take that request.

No argument date has been set. The court is expected to decide early in 2027 whether to hear the case.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:11800:11889/full/pct:25/0/default.jpg', 'The U.S. Supreme Court building, Washington, D.C. (file). Photo: Carol M. Highsmith / Library of Congress (highsm.11889), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-16.sql', 6, 0, 'newsroom-assistant', '2026-11-16T10:50:00.000Z', '2026-11-16T10:50:00.000Z');
